import 'package:flutter_agent_harness/flutter_agent_harness.dart';

import '../test/integration/trajectory/mock_session.dart';

Future<void> main() async {
  final script = MockSessionScript()
    ..contextInject('repo context: flutter_agent_harness')
    ..modelChange(provider: 'openai', modelId: 'gpt-mock')
    ..turn(
      'fix the bug',
      toolCalls: [
        const MockToolCallSpec('call-1', name: 'read', args: {'path': 'lib/x.dart'}),
      ],
    )
    ..assistantText('patched and verified')
    ..checkpoint(messageCount: 6, goal: 'investigate flaky test');
  script.compaction(summary: 'compacted summary', firstKeptEntryId: script.stepId(6));
  script
    ..user('continue')
    ..assistantText(
      'finished',
      usage: const Usage(
        input: 200,
        output: 40,
        cacheRead: 0,
        cacheWrite: 0,
        totalTokens: 240,
        cost: UsageCost(total: 0.03),
      ),
    );

  final root = Directory.systemTemp.createTempSync('repro_sess_');
  final fixture = await MockSessionFixture.build(script, sessionsRoot: root);
  final records = await fixture.readBack();

  // CLI path: appendAll, one snapshot.
  final bulk = TrajectorySnapshotBuilder().appendAll(records);
  print('== appendAll ==');
  for (final r in bulk.requests) {
    print('${r.seq} ${r.turn}/${r.step} ${r.model.isEmpty ? "compaction" : r.model} '
        'usage=${r.usage?.totalTokens} cum=${r.cumulativeUsage?.totalTokens}');
  }

  // Live path: per-append snapshots.
  final live = TrajectorySnapshotBuilder();
  TrajectorySnapshot? last;
  for (final record in records) {
    last = live.append(record);
  }
  print('== live tail ==');
  for (final r in last!.requests) {
    print('${r.seq} ${r.turn}/${r.step} ${r.model.isEmpty ? "compaction" : r.model} '
        'usage=${r.usage?.totalTokens} cum=${r.cumulativeUsage?.totalTokens}');
  }
}

