/// the session store is pinned with `--session-root` per call.
Future<FaResult> runFaTrajectory(
  List<String> args, {
  String? sessionRoot,
}) async {
  // gh-1300: honor the FA_BIN AOT seam (compiled ONCE per CI shard).
  final command = faCliCommand(
    [
      'trajectory',
      ...args,
      '--session-root',
      sessionRoot ?? sessionsRoot.path,
